 android.view.View projectIcon(String name){
 String resource=name.equals("fragment-logo-editor")?"fragment_original":name.equals("enduro-club-downloads")?"enduro_original":name.equals("my-projects")?"icon":"";
 if(!resource.isEmpty()){ImageView original=new ImageView(this);original.setImageDrawable(getDrawable(getResources().getIdentifier(resource,"drawable",getPackageName())));original.setScaleType(ImageView.ScaleType.FIT_CENTER);original.setContentDescription("Оригинальный логотип "+name);return original;}

 String lower=name.toLowerCase(java.util.Locale.ROOT);String symbol;int color;
 if(name.equals("my-projects")){symbol="◈";color=0xff274c32;}
 else if(lower.contains("camara")||lower.contains("camera")){symbol="📷";color=0xff274c62;}
 else if(lower.contains("enduro")||lower.contains("moto")){symbol="🏍";color=0xff604523;}
 else if(lower.contains("logo")||lower.contains("editor")){symbol="🎨";color=0xff4b365f;}
 else if(lower.contains("float")){symbol="🛟";color=0xff245b58;}
 else if(lower.contains("hello")){symbol="👋";color=0xff59394b;}
 else{String[] words=name.split("[-_ ]+");symbol=words[0].substring(0,Math.min(1,words[0].length()));if(words.length>1&&!words[1].isEmpty())symbol+=words[1].substring(0,1);symbol=symbol.toUpperCase(java.util.Locale.ROOT);int[] colors={0xff274c62,0xff604523,0xff4b365f,0xff245b58,0xff59394b};color=colors[(name.hashCode()&0x7fffffff)%colors.length];}
 TextView icon=label(symbol,26,white);icon.setGravity(android.view.Gravity.CENTER);icon.setPadding(0,0,0,0);icon.setContentDescription("Значок проекта "+name);android.graphics.drawable.GradientDrawable shape=new android.graphics.drawable.GradientDrawable();shape.setColor(color);shape.setCornerRadius(dp(16));icon.setBackground(shape);return icon;
 }
