 String sha256(File f)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)md.update(b,0,n);}StringBuilder hex=new StringBuilder();for(byte b:md.digest())hex.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return hex.toString();}
 android.content.pm.Signature[] signatures(android.content.pm.PackageInfo p){return Build.VERSION.SDK_INT>=28?(p.signingInfo==null?null:p.signingInfo.getApkContentsSigners()):p.signatures;}
 void verifyUpdate(File file,JSONObject release)throws Exception{
  if(!release.getString("sha256").equals(sha256(file)))throw new IOException("Контрольная сумма APK не совпадает");
  int flags=Build.VERSION.SDK_INT>=28?android.content.pm.PackageManager.GET_SIGNING_CERTIFICATES:android.content.pm.PackageManager.GET_SIGNATURES;
  android.content.pm.PackageInfo archive=getPackageManager().getPackageArchiveInfo(file.getAbsolutePath(),flags),installed=getPackageManager().getPackageInfo(getPackageName(),flags);
  if(archive==null||!getPackageName().equals(archive.packageName)||archive.versionCode!=release.getInt("versionCode")||archive.versionCode<=installed.versionCode)throw new IOException("APK не соответствует версии приложения");
  android.content.pm.Signature[] a=signatures(archive),b=signatures(installed);if(a==null||b==null||a.length!=b.length)throw new IOException("Не удалось проверить подпись APK");for(int i=0;i<a.length;i++)if(!a[i].equals(b[i]))throw new IOException("Подпись APK отличается от установленного приложения");
 }
 void downloadUpdate(JSONObject release){
  if(downloadingUpdate)return;if(!UpdatePolicy.trustedUrl(release.optString("apkUrl"))||!UpdatePolicy.validHash(release.optString("sha256"))){updateMessage("Некорректная ссылка обновления");return;}
  downloadingUpdate=true;downloadDialog=new ProgressDialog(this);downloadDialog.setTitle("Обновление приложения");downloadDialog.setMessage("Скачиваю APK и проверяю подпись…");downloadDialog.setCancelable(false);downloadDialog.show();
  updateExecutor.execute(()->{File temp=null;try{File dir=new File(getCacheDir(),"updates");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Нет места для обновления");temp=new File(dir,"download.tmp");HttpURLConnection c=(HttpURLConnection)new URL(release.getString("apkUrl")).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(25000);long count=0;
   try{if(c.getResponseCode()!=200)throw new IOException("Не удалось скачать APK");try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(temp)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){count+=n;if(count>52428800)throw new IOException("APK превышает допустимый размер");out.write(b,0,n);}}}finally{c.disconnect();}
   long expected=release.optLong("sizeBytes",-1);if(expected>=0&&count!=expected)throw new IOException("APK скачан не полностью");verifyUpdate(temp,release);File ready=new File(dir,"update.apk");if(ready.exists()&&!ready.delete())throw new IOException("Не удалось сохранить APK");if(!temp.renameTo(ready))throw new IOException("Не удалось сохранить APK");verifiedUpdate=ready;runOnUiThread(()->{dismissDownload();if(!isFinishing()&&!isDestroyed())installUpdate();});
  }catch(Exception e){if(temp!=null)temp.delete();final String error=e instanceof IOException&&e.getMessage()!=null?e.getMessage():"Не удалось подготовить обновление";runOnUiThread(()->{dismissDownload();updateMessage(error+". Можно повторить позже.");});}finally{downloadingUpdate=false;}});
 }
 void dismissDownload(){if(downloadDialog!=null){downloadDialog.dismiss();downloadDialog=null;}}
 void installUpdate(){if(verifiedUpdate==null||!verifiedUpdate.isFile())return;if(!getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(this).setTitle("Разрешить установку обновлений").setMessage("Android просит разрешить установку из «Мои проекты». После возврата откроется установка APK.").setPositiveButton("Настройки",(d,w)->{try{startActivityForResult(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())),INSTALL_PERMISSION);}catch(Exception e){updateMessage("Не удалось открыть настройки установки");}}).setNegativeButton("Позже",(d,w)->{}).show();return;}
  try{Intent intent=new Intent(Intent.ACTION_VIEW);intent.setDataAndType(Uri.parse("content://"+getPackageName()+".updates/update.apk"),"application/vnd.android.package-archive");intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(intent);}catch(Exception e){updateMessage("Не удалось открыть установщик Android. APK доступен на странице приложения.");}
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==INSTALL_PERMISSION){if(getPackageManager().canRequestPackageInstalls())installUpdate();else updateMessage("Разрешение не выдано. Обновление можно повторить позже.");}}
